WITH matched_keys AS (SELECT status FROM accounts EXCEPT DISTINCT SELECT status FROM accounts WHERE opened_date >= '2023-06-01'), verified AS (SELECT s.* FROM accounts s INNER JOIN matched_keys k ON s.status = k.status) SELECT s.customer_id, s.account_type, s.balance, (SELECT AVG(s2.monthly_fee) FROM subscriptions s2 WHERE s2.customer_id = s.customer_id) AS avg_subscription_monthly_fee FROM verified s ORDER BY balance NULLS LAST;
